# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorDetails {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface Props {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (details: ErrorDetails) => void;
  resetKeys?: unknown[];        // reset boundary when these values change
  isolate?: boolean;            // wrap in its own visual container
}

interface State {
  hasError: boolean;
  errorDetails: ErrorDetails | null;
  retryCount: number;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  retryCount: number;
  retry: () => void;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

function logError(details: ErrorDetails, retryCount: number): void {
  const { error, errorInfo, timestamp } = details;

  console.group(
    `%c⛔ React Error Boundary — ${timestamp.toISOString()}`,
    "color: #ef4444; font-weight: bold; font-size: 14px;"
  );
  console.error("Error:", error.message);
  console.error("Stack:", error.stack);
  console.error("Component Stack:", errorInfo.componentStack);
  console.info("Retry attempts so far:", retryCount);
  console.groupEnd();

  // Forward to external monitoring (Sentry, Datadog, etc.)
  if (typeof window !== "undefined" && (window as any).__errorMonitor) {
    (window as any).__errorMonitor.captureException(error, {
      extra: { componentStack: errorInfo.componentStack, retryCount },
    });
  }
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({ error, retryCount, retry }: FallbackProps) {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div role="alert" style={styles.container}>
      <div style={styles.card}>
        {/* Icon */}
        <div style={styles.iconWrapper}>
          <svg
            style={styles.icon}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="8" x2="12" y2="12" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </svg>
        </div>

        {/* Heading */}
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.subtext}>
          An unexpected error occurred while rendering this component.
        </p>

        {/* Error message */}
        <div style={styles.errorBox}>
          <code style={styles.errorMessage}>{error.message}</code>
        </div>

        {/* Retry info */}
        {retryCount > 0 && (
          <p style={styles.retryBadge}>
            ↺ Retry attempt {retryCount}
          </p>
        )}

        {/* Actions */}
        <div style={styles.actions}>
          <button onClick={retry} style={styles.retryButton}>
            Try Again
          </button>
          <button
            onClick={() => setShowDetails((v) => !v)}
            style={styles.detailsButton}
          >
            {showDetails ? "Hide" : "Show"} Details
          </button>
        </div>

        {/* Collapsible stack trace */}
        {showDetails && (
          <pre style={styles.stackTrace}>
            {error.stack ?? "No stack trace available."}
          </pre>
        )}
      </div>
    </div>
  );
}

// ─── Error Boundary Class ─────────────────────────────────────────────────────

export class ErrorBoundary extends Component<Props, State> {
  private prevResetKeys: unknown[];

  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, errorDetails: null, retryCount: 0 };
    this.prevResetKeys = props.resetKeys ?? [];
  }

  // Triggered during render — update state so next render shows fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true };
  }

  // Triggered after render — side-effects (logging) go here
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const details: ErrorDetails = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? "",
    };

    this.setState({ errorDetails: details });
    logError(details, this.state.retryCount);
    this.props.onError?.(details);
  }

  // Reset when resetKeys change (similar to react-error-boundary)
  componentDidUpdate(prevProps: Props): void {
    const { resetKeys = [] } = this.props;
    if (
      this.state.hasError &&
      resetKeys.some((key, i) => key !== this.prevResetKeys[i])
    ) {
      this.handleRetry();
    }
    this.prevResetKeys = resetKeys;
  }

  handleRetry = (): void => {
    this.setState((prev) => ({
      hasError: false,
      errorDetails: null,
      retryCount: prev.retryCount + 1,
    }));
  };

  render(): ReactNode {
    const { hasError, errorDetails, retryCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && errorDetails) {
      const fallbackProps: FallbackProps = {
        error: errorDetails.error,
        errorInfo: errorDetails.errorInfo,
        retryCount,
        retry: this.handleRetry,
      };

      const ui = fallback ? fallback(fallbackProps) : <DefaultFallback {...fallbackProps} />;
      return isolate ? <div style={styles.isolateWrapper}>{ui}</div> : ui;
    }

    return children;
  }
}

// ─── Convenience HOC ─────────────────────────────────────────────────────────

export function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  boundaryProps?: Omit<Props, "children">
) {
  const displayName =
    WrappedComponent.displayName ?? WrappedComponent.name ?? "Component";

  function WithBoundary(props: P) {
    return (
      <ErrorBoundary {...boundaryProps}>
        <WrappedComponent {...props} />
      </ErrorBoundary>
    );
  }

  WithBoundary.displayName = `withErrorBoundary(${displayName})`;
  return WithBoundary;
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "200px",
    padding: "24px",
    fontFamily: "system-ui, -apple-system, sans-serif",
  },
  card: {
    maxWidth: "480px",
    width: "100%",
    background: "#fff",
    border: "1px solid #fca5a5",
    borderRadius: "12px",
    padding: "32px",
    boxShadow: "0 4px 24px rgba(239,68,68,0.08)",
    textAlign: "center",
  },
  iconWrapper: {
    display: "flex",
    justifyContent: "center",
    marginBottom: "16px",
  },
  icon: {
    width: "48px",
    height: "48px",
    color: "#ef4444",
  },
  heading: {
    margin: "0 0 8px",
    fontSize: "20px",
    fontWeight: 700,
    color: "#111827",
  },
  subtext: {
    margin: "0 0 16px",
    fontSize: "14px",
    color: "#6b7280",
  },
  errorBox: {
    background: "#fef2f2",
    border: "1px solid #fecaca",
    borderRadius: "6px",
    padding: "10px 14px",
    marginBottom: "12px",
    textAlign: "left",
  },
  errorMessage: {
    fontSize: "13px",
    color: "#b91c1c",
    wordBreak: "break-word",
  },
  retryBadge: {
    fontSize: "12px",
    color: "#9ca3af",
    margin: "0 0 16px",
  },
  actions: {
    display: "flex",
    gap: "10px",
    justifyContent: "center",
    marginBottom: "16px",
  },
  retryButton: {
    padding: "8px 20px",
    background: "#ef4444",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    fontSize: "14px",
    fontWeight: 600,
    cursor: "pointer",
  },
  detailsButton: {
    padding: "8px 20px",
    background: "transparent",
    color: "#6b7280",
    border: "1px solid #d1d5db",
    borderRadius: "6px",
    fontSize: "14px",
    cursor: "pointer",
  },
  stackTrace: {
    textAlign: "left",
    background: "#111827",
    color: "#f9fafb",
    borderRadius: "6px",
    padding: "14px",
    fontSize: "11px",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-all",
    maxHeight: "200px",
    overflowY: "auto",
  },
  isolateWrapper: {
    border: "2px dashed #fca5a5",
    borderRadius: "8px",
  },
};
