## Usage Examples

```tsx
// App.tsx
import { ErrorBoundary, withErrorBoundary } from "./ErrorBoundary";

// ── 1. Basic wrapping ─────────────────────────────────────────────────────────
function App() {
  return (
    <ErrorBoundary>
      <MyComponent />
    </ErrorBoundary>
  );
}

// ── 2. Custom fallback UI ─────────────────────────────────────────────────────
function AppWithCustomFallback() {
  return (
    <ErrorBoundary
      fallback={({ error, retry, retryCount }) => (
        <div>
          <p>Oops: {error.message}</p>
          <button onClick={retry}>Retry ({retryCount})</button>
        </div>
      )}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}

// ── 3. External error reporting ───────────────────────────────────────────────
function AppWithReporting() {
  return (
    <ErrorBoundary
      onError={({ error, componentStack, timestamp }) => {
        fetch("/api/log-error", {
          method: "POST",
          body: JSON.stringify({ message: error.message, componentStack, timestamp }),
        });
      }}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}

// ── 4. Auto-reset when route changes ─────────────────────────────────────────
function AppWithResetKeys() {
  const { pathname } = useLocation();
  return (
    <ErrorBoundary resetKeys={[pathname]}>
      <MyComponent />
    </ErrorBoundary>
  );
}

// ── 5. HOC pattern ────────────────────────────────────────────────────────────
const SafeWidget = withErrorBoundary(Widget, {
  isolate: true,
  onError: (details) => console.warn("Widget failed:", details),
});

// ── 6. Nested boundaries (granular isolation) ─────────────────────────────────
function Dashboard() {
  return (
    <ErrorBoundary>          {/* page-level catch-all */}
      <Header />
      <ErrorBoundary isolate> {/* sidebar fails independently */}
        <Sidebar />
      </ErrorBoundary>
      <ErrorBoundary isolate> {/* main content fails independently */}
        <MainContent />
      </ErrorBoundary>
    </ErrorBoundary>
  );
}
```

---

## Key Design Decisions

| Feature | Approach |
|---|---|
| **Error capture** | `getDerivedStateFromError` (pure) + `componentDidCatch` (side-effects) |
| **Retry** | Increments counter, resets state — child remounts fresh |
| **Reset keys** | `componentDidUpdate` diff, mirrors `react-error-boundary` API |
| **Logging** | Grouped `console` output + optional external monitor hook |
| **Custom fallback** | Render-prop pattern gives full control |
| **HOC** | `withErrorBoundary` for decorator-style usage |
| **Isolation** | `isolate` prop adds dashed border so broken widget is visually scoped |
| **Stack trace** | Collapsible in UI, always logged to console |
